def get_with_retry(s, url, tries=5):
    # Purpose: GET a Meraki URL, waiting when rate limited
    for _ in range(tries):
        r = s.get(url)
        if r.status_code != ⟦1⟧:
            return r
        time.sleep(int(r.headers.get("⟦2⟧", 1)))
    raise RuntimeError("Still rate limited")
